CREATE OR REPLACE FUNCTION private.audit_redact(p_doc jsonb, p_changed text[] DEFAULT '{}'::text[], p_prefix text DEFAULT ''::text, p_depth integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  c_max_depth constant integer := 12;
  v_out jsonb;
begin
  if jsonb_typeof(p_doc) in ('object', 'array') and p_depth >= c_max_depth then
    return to_jsonb('[redacted: too deep]'::text);
  elsif jsonb_typeof(p_doc) = 'object' then
    select coalesce(jsonb_object_agg(e.key,
             case
               when private.audit_is_secret_key(e.key) or private.audit_is_pii_key(e.key) then  -- 655
                 case
                   when e.value = 'null'::jsonb or e.value = '""'::jsonb then e.value
                   when private.audit_is_pii_key(e.key) and e.value = '[]'::jsonb then e.value  -- 655
                   when (p_prefix || e.key) = any (p_changed) then to_jsonb('[redacted: changed]'::text)
                   else to_jsonb('[redacted]'::text)
                 end
               else private.audit_redact(e.value, p_changed, p_prefix || e.key || '.', p_depth + 1)
             end), '{}'::jsonb)
      into v_out
      from jsonb_each(p_doc) as e;
    return v_out;
  elsif jsonb_typeof(p_doc) = 'array' then
    select coalesce(jsonb_agg(private.audit_redact(a.value, p_changed, p_prefix || (a.ord - 1)::text || '.', p_depth + 1)
                              order by a.ord), '[]'::jsonb)
      into v_out
      from jsonb_array_elements(p_doc) with ordinality as a(value, ord);
    return v_out;
  end if;
  return p_doc;
end;
$function$

CREATE OR REPLACE FUNCTION private.audit_secret_paths(p_doc jsonb, p_prefix text DEFAULT ''::text, p_depth integer DEFAULT 0)
 RETURNS TABLE(path text, val jsonb)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  c_max_depth constant integer := 12;  -- the same cap as audit_redact
  r record;
begin
  if jsonb_typeof(p_doc) = 'object' then
    for r in select e.key, e.value from jsonb_each(p_doc) as e loop
      if private.audit_is_secret_key(r.key) or private.audit_is_pii_key(r.key) then  -- 655
        path := p_prefix || r.key;
        val := r.value;
        return next;
      elsif jsonb_typeof(r.value) in ('object', 'array') and p_depth + 1 >= c_max_depth then
        -- Too deep to look inside: report the subtree whole, as a
        -- possible secret (audit_redact masks it "[redacted: too deep]").
        path := p_prefix || r.key;
        val := r.value;
        return next;
      elsif jsonb_typeof(r.value) in ('object', 'array') then
        return query select s.path, s.val
          from private.audit_secret_paths(r.value, p_prefix || r.key || '.', p_depth + 1) as s;
      end if;
    end loop;
  elsif jsonb_typeof(p_doc) = 'array' then
    for r in select a.value, a.ord from jsonb_array_elements(p_doc) with ordinality as a(value, ord) loop
      if jsonb_typeof(r.value) in ('object', 'array') and p_depth + 1 >= c_max_depth then
        path := p_prefix || (r.ord - 1)::text;
        val := r.value;
        return next;
      elsif jsonb_typeof(r.value) in ('object', 'array') then
        return query select s.path, s.val
          from private.audit_secret_paths(r.value, p_prefix || (r.ord - 1)::text || '.', p_depth + 1) as s;
      end if;
    end loop;
  end if;
  return;
end;
$function$

CREATE OR REPLACE FUNCTION private.contact_studios_upsert(p_contact_id uuid, p_location_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  d record;
  e record;
BEGIN
  SELECT * INTO d FROM public.derive_contact_studio(p_contact_id, p_location_id);
  SELECT * INTO e FROM public.contact_studios WHERE contact_id = p_contact_id AND location_id = p_location_id;
  IF d.kind IS NULL THEN
    IF FOUND AND e.status = 'active' THEN
      UPDATE public.contact_studios SET status = 'ended', ended_at = now()
       WHERE contact_id = p_contact_id AND location_id = p_location_id;
      RETURN 'ended';
    END IF;
    RETURN CASE WHEN FOUND THEN 'unchanged' ELSE 'none' END;
  END IF;
  IF NOT FOUND THEN
    INSERT INTO public.contact_studios (contact_id, location_id, organization_id, kind, status, source, stage_slug, first_seen_at, last_seen_at, ended_at)
    VALUES (p_contact_id, p_location_id, (SELECT organization_id FROM public.locations WHERE id = p_location_id),
            d.kind, d.status, d.source, d.stage_slug, d.first_seen_at, d.last_seen_at,
            CASE WHEN d.status = 'ended' THEN now() END);
    RETURN 'inserted';
  END IF;
  IF (e.kind, e.status, e.source, e.stage_slug) IS NOT DISTINCT FROM (d.kind, d.status, d.source, d.stage_slug)
     AND e.first_seen_at <= d.first_seen_at
     AND (d.last_seen_at IS NULL OR e.last_seen_at >= d.last_seen_at) THEN
    RETURN 'unchanged';
  END IF;
  UPDATE public.contact_studios
     SET kind = d.kind,
         status = d.status,
         source = d.source,
         stage_slug = d.stage_slug,
         first_seen_at = LEAST(first_seen_at, d.first_seen_at),
         last_seen_at = GREATEST(last_seen_at, d.last_seen_at),
         ended_at = CASE WHEN d.status = 'ended' THEN coalesce(ended_at, now()) ELSE NULL END
   WHERE contact_id = p_contact_id AND location_id = p_location_id;
  RETURN CASE WHEN e.status = 'active' AND d.status = 'ended' THEN 'ended' ELSE 'updated' END;
END;
$function$

CREATE OR REPLACE FUNCTION private.wa_phone_from_phone(raw text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  d text;
  explicit_intl boolean;
  was_irish_local boolean;
begin
  if raw is null or btrim(raw) = '' then return null; end if;

  explicit_intl := raw ~ '^\s*(\+|00)';
  d := regexp_replace(raw, '[^0-9]', '', 'g');
  if d like '00%' then d := substring(d from 3); end if;

  was_irish_local := d ~ '^08[35679][0-9]{7}$';
  if was_irish_local then d := '353' || substring(d from 2); end if;

  if d = '10000000000' then return null; end if;
  if d ~ '^(.)\1+$' then return null; end if;
  if d like '0%' then return null; end if;
  if length(d) < 9 or length(d) > 15 then return null; end if;
  if d like '353%' and d !~ '^3538[35679][0-9]{7}$' then return null; end if;
  if d like '44%'  and d !~ '^447[0-9]{9}$'         then return null; end if;

  if explicit_intl
     or was_irish_local
     or d ~ '^3538[35679][0-9]{7}$'
     or d ~ '^447[0-9]{9}$'
  then
    return d;
  end if;
  return null;
end;
$function$
